<?php

require_once __DIR__ . '/../include/bittorrent.php';
dbconn();
loggedinorreturn();

$isManager = nova_official_seed_is_manager();
$uid = (int)$CURUSER['id'];
$scope = $isManager && (int)($_GET['user_id'] ?? 0) > 0 ? (int)$_GET['user_id'] : ($isManager ? 0 : $uid);
$where = $scope > 0 ? ' WHERE user_id = ' . $scope : '';

function nova_activity_rows(string $sql): array {
    $result = sql_query($sql);
    $rows = [];
    while ($result && ($row = mysql_fetch_assoc($result))) $rows[] = $row;
    return $rows;
}

$magicSummary = mysql_fetch_assoc(sql_query('SELECT COALESCE(SUM(reward_amount),0) AS magic_total, COUNT(*) AS reward_count, COUNT(DISTINCT user_id) AS users FROM nova_official_seed_magic_reward_events' . $where));
$uploadSummary = mysql_fetch_assoc(sql_query('SELECT COALESCE(SUM(reward_bytes),0) AS upload_total, COUNT(*) AS reward_count, COUNT(DISTINCT user_id) AS users FROM nova_official_seed_reward_events' . $where));
$magicRows = nova_activity_rows('SELECT e.*, u.username FROM nova_official_seed_magic_reward_events e JOIN users u ON u.id=e.user_id' . ($scope > 0 ? ' WHERE e.user_id=' . $scope : '') . ' ORDER BY e.id DESC LIMIT 240');
$uploadRows = nova_activity_rows('SELECT e.*, u.username, t.name FROM nova_official_seed_reward_events e JOIN users u ON u.id=e.user_id LEFT JOIN torrents t ON t.id=e.torrent_id' . ($scope > 0 ? ' WHERE e.user_id=' . $scope : '') . ' ORDER BY e.id DESC LIMIT 240');
$userRows = $isManager ? nova_activity_rows("SELECT u.id,u.username,COALESCE(m.magic_total,0) AS magic_total,COALESCE(v.upload_total,0) AS upload_total,COALESCE(m.reward_count,0) AS magic_count,COALESCE(v.reward_count,0) AS upload_count FROM users u JOIN (SELECT user_id FROM nova_official_seed_magic_reward_events UNION SELECT user_id FROM nova_official_seed_reward_events) r ON r.user_id=u.id LEFT JOIN (SELECT user_id,SUM(reward_amount) magic_total,COUNT(*) reward_count FROM nova_official_seed_magic_reward_events GROUP BY user_id) m ON m.user_id=u.id LEFT JOIN (SELECT user_id,SUM(reward_bytes) upload_total,COUNT(*) reward_count FROM nova_official_seed_reward_events GROUP BY user_id) v ON v.user_id=u.id ORDER BY m.magic_total DESC, v.upload_total DESC LIMIT 500") : [];

stdhead('活动奖励');
?>
