<?php if ($isManager): ?><section class="nova-ar-panel"><div class="nova-ar-head"><h2>活动详细统计表</h2><form class="nova-ar-filter" method="get"><input type="number" min="1" name="user_id" placeholder="用户 ID" value="<?= $scope ?: '' ?>"><button>筛选</button></form></div><div class="nova-ar-scroll"><table class="nova-ar-table"><thead><tr><th>用户</th><th>活动魔力</th><th>魔力记录</th><th>上传量奖励</th><th>上传记录</th></tr></thead><tbody><?php foreach($userRows as $row): ?><tr><td><a href="userdetails.php?id=<?= (int)$row['id'] ?>"><?= htmlspecialchars($row['username']) ?></a> (#<?= (int)$row['id'] ?>)</td><td class="nova-ar-magic"><?= number_format((float)$row['magic_total'],2) ?></td><td><?= (int)$row['magic_count'] ?></td><td class="nova-ar-upload"><?= htmlspecialchars(mksize((int)$row['upload_total'])) ?></td><td><?= (int)$row['upload_count'] ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<section class="nova-ar-panel"><div class="nova-ar-head"><h2>活动魔力奖励明细</h2><span><?= $isManager ? '显示全站最近 240 条记录' : '仅显示您的奖励记录' ?></span></div><div class="nova-ar-scroll"><table class="nova-ar-table"><thead><tr><?php if($isManager): ?><th>用户</th><?php endif; ?><th>奖励魔力</th><th>保种官种</th><th>官种加成</th><th>结算时间</th></tr></thead><tbody><?php foreach($magicRows as $row): ?><tr><?php if($isManager): ?><td><?= htmlspecialchars($row['username']) ?></td><?php endif; ?><td class="nova-ar-magic"><?= number_format((float)$row['reward_amount'],5) ?></td><td><?= (int)$row['torrent_count'] ?></td><td><?= number_format((float)$row['official_percent'],2) ?>%</td><td><?= htmlspecialchars($row['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$magicRows): ?><tr><td colspan="<?= $isManager ? 5 : 4 ?>">暂时没有活动魔力奖励记录</td></tr><?php endif; ?></tbody></table></div></section>
<section class="nova-ar-panel"><div class="nova-ar-head"><h2>上传量奖励明细</h2><span>连续保种满 15 天后开始发放</span></div><div class="nova-ar-scroll"><table class="nova-ar-table"><thead><tr><?php if($isManager): ?><th>用户</th><?php endif; ?><th>资源</th><th>档位</th><th>奖励上传量</th><th>发放时间</th></tr></thead><tbody><?php foreach($uploadRows as $row): ?><tr><?php if($isManager): ?><td><?= htmlspecialchars($row['username']) ?></td><?php endif; ?><td class="name"><a href="details.php?id=<?= (int)$row['torrent_id'] ?>"><?= htmlspecialchars($row['name'] ?: ('#'.$row['torrent_id'])) ?></a></td><td><?= (int)$row['tier_days'] ?> 天</td><td class="nova-ar-upload"><?= htmlspecialchars(mksize((int)$row['reward_bytes'])) ?></td><td><?= htmlspecialchars($row['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$uploadRows): ?><tr><td colspan="<?= $isManager ? 5 : 4 ?>">暂时没有上传量奖励记录</td></tr><?php endif; ?></tbody></table></div></section></main>
<?php stdfoot();
